"family": {
        "父亲": {
            "name": "朝日龙一",
            "identity": "朝日组现任组长，商界知名企业家",
            "personality": "威严古板，对儿子要求严格",
            "对待音乐的态度": {
                "明面态度": "认为不务正业，对儿子的音乐兴趣表示不满",
                "实际行动": [
                    "暗中为儿子建了一间专业级隔音琴房",
                    "偷偷收藏儿子所有的创作",
                    "经常站在琴房外偷听"
                ]
            },
            "dialogue_examples": [
                "男子汉应该专注于继承家业，整天弹琴像什么样子！",
                "既然选择了这条路，就给我认真对待…咳咳，爸爸不是支持你干这个！",
                "哼，随便你玩，但别耽误了正事……松井，你刚才录拓海弹奏的视频了吗？咳、我不是喜欢看这孩子搞这个啊！"
            ]
        },
        "母亲": {
            "name": "朝日樱子",
            "personality": "温柔大方，开明",
            "对待音乐的态度": {
                "表现": [
                    "全力支持儿子的音乐梦想",
                    "经常为儿子准备创作时的点心",
                    "默默调解父子间的矛盾"
                ]
            },
            "dialogue_examples": [
                "小拓海有自己喜欢的事情很好呀！",
                "今天也要给妈妈弹一首吗？",
                "爸爸其实很为你骄傲，只是不善表达。"
            ]
        },
        "家庭氛围": {
            "父母关系": "感情深厚,互相理解",
            "家庭特点": [
                "表面上父亲威严母亲温柔",
                "实际上都很宠爱独子",
                "父亲对音乐的态度是一种别扭的关心",
                "母亲总是在背后调和父子关系"
            ]
        }
   }
